  const hits = (ws.contentDiscovery || []).filter(r => r.distinctFromBaseline);
  if (hits.length) {
    p('| Path | Status | Source |');
    p('|---|---|---|');
    for (const h of hits) p(`| \`${h.path}\` | ${h.status} | ${h.fromJsBundle ? 'discovered in JS bundle (not linked anywhere)' : 'wordlist'} |`);
  } else { p(`- No genuine hits out of ${(ws.contentDiscovery || []).length} paths checked (all matched the site's baseline/soft-404 response).`); }
  p('');
  p('### Technology Fingerprint');
  if (ws.fingerprint && ws.fingerprint.evidenceStrings.length) {
    for (const e of ws.fingerprint.evidenceStrings.slice(0, 15)) p(`- ${e}`);
  } else { p('- No fingerprint evidence collected.'); }
  p('');
  p('### Forms / Parameter Surface');
  if (ws.forms && ws.forms.length) {
    for (const f of ws.forms) p(`- \`${f.method} ${f.action}\` - fields: ${f.fields.join(', ')} (page: ${f.page})`);
  } else { p('- No server-rendered \\<form\\> elements found (common for JS-driven SPAs - the real submit targets are the discovered API paths above, not HTML forms).'); }
  p('');
} else {
  p(`Web scan not reachable/not run - ${ctx.webScan ? ctx.webScan.reason : 'no web target'}.`);
  p('');
}

p('### Vulnerable Components (retire.js against fetched JS bundle)');
if (ctx.componentFindings && ctx.componentFindings.length) {
  for (const c of ctx.componentFindings) {
    p(`- **${c.component} ${c.version}** - severity ${c.severity}${c.cve.length ? ', ' + c.cve.join(', ') : ''}: ${c.summary || 'see info links'}`);
  }
} else { p('- retire.js scan ran, no known-vulnerable component versions matched.'); }
p('');

p('### SQL Injection Testing (sqlmap)');
if (!ctx.sqlmapScan || ctx.sqlmapScan.skipped) {
  p(`- Not run (${ctx.sqlmapScan ? ctx.sqlmapScan.reason : 'toggle off'}).`);
} else if (ctx.sqlmapScan.vulnerable) {
  for (const f of ctx.sqlmapScan.findings) p(`- Parameter \`${f.parameter}\`: ${f.type || 'injectable'} - ${f.title || ''}`);
} else { p('- sqlmap ran (`--crawl=2 --forms --level=1 --risk=1`), no injectable parameters found.'); }
p('');

p('### Web Vulnerability Scan (OWASP ZAP)');
if (!ctx.zapScan || ctx.zapScan.skipped) {
  p(`- Not run (${ctx.zapScan ? ctx.zapScan.reason : 'toggle off'}).`);
} else if (!ctx.zapScan.reachable) {
  p(`- Attempted, ZAP unreachable (${ctx.zapScan.reason}).`);
} else if (ctx.zapScan.alertCount === 0) {
  p('- ZAP spider + active scan completed, no alerts raised.');
} else {
  p(`- ZAP spider complete: ${ctx.zapScan.spiderComplete}, active scan complete: ${ctx.zapScan.activeScanComplete}, ${ctx.zapScan.alertCount} alert(s):`);
  const byName = {};
  for (const a of ctx.zapScan.alerts) {
    byName[a.name] = byName[a.name] || { risk: a.risk, urls: [] };
    if (byName[a.name].urls.length < 5) byName[a.name].urls.push(a.url);
  }
  for (const [name, info] of Object.entries(byName)) {
    p(`  - **${name}** (${info.risk}): ${info.urls.join(', ')}`);
  }
}
p('');

// --- 8. Testing Coverage & Gaps ---
p('## 8. Testing Coverage & Gaps');
p('');
p('| Category | Tested this scan? |');
p('|---|---|');
p(`| DNS/WHOIS/Subdomain enumeration | Yes |`);
p(`| Port scanning | ${ctx.portScan && !ctx.portScan.skipped ? 'Yes' : 'No - scanIntensity below dns+ports'} |`);
p(`| Security headers / cookie flags | ${ctx.webScan && ctx.webScan.reachable ? 'Yes' : 'No - web target unreachable/not scanned'} |`);
p(`| Content discovery (baselined) | ${ctx.webScan && ctx.webScan.reachable ? 'Yes' : 'No'} |`);
p(`| Vulnerable components (retire.js) | ${ctx.componentFindings !== undefined ? 'Yes' : 'No'} |`);
p(`| SQL/NoSQL injection (sqlmap) | ${ctx.sqlmapScan && !ctx.sqlmapScan.skipped ? 'Yes' : 'No - toggle off or web unreachable'} |`);
p(`| XSS / broader web vuln scan (ZAP) | ${ctx.zapScan && !ctx.zapScan.skipped && ctx.zapScan.reachable ? 'Yes' : 'No - toggle off, ZAP not running, or web unreachable'} |`);
p(`| Broken Authentication (rate-limiting, JWT weaknesses, password reset flaws) | No - requires active authenticated testing not performed by this scan |`);
p(`| Broken Access Control / IDOR | No - requires authenticated, session-aware testing |`);
p(`| Broken Anti-Automation | No - requires repeated-request active testing |`);
p(`| Cryptographic Issues (TLS/cipher grade) | No - not implemented in this scan |`);
p(`| XML External Entities (XXE) | No - requires crafted payloads to file-upload endpoints |`);
p(`| Insecure Deserialization | No - requires crafted payload testing |`);
p(`| Insufficient Logging & Monitoring | Not detectable from external recon - requires server-side log access |`);
p('');

const fullText = lines.join('\n');
const splitIdx = fullText.indexOf('## 8. Testing Coverage & Gaps');
const sections1to5 = splitIdx >= 0 ? fullText.slice(0, splitIdx) : fullText;
const section8 = splitIdx >= 0 ? fullText.slice(splitIdx) : '';
return [{ json: { ...ctx, sections1to5, section8 } }];

const ctx = $('Parse Component Findings').item.json;
let text = $json.text || $json.output || '';
text = text.replace(/^[\s\S]*?<\/think>\s*/i, '').trim();
// Untagged models ramble then give the real answer as a final block, not
// always separated by a blank line - split on single newlines too and take
// the last non-empty chunk as the answer.
if (text.length > 400) {
  const chunks = text.split(/\n+/).map(c => c.trim()).filter(Boolean);
  if (chunks.length > 1) text = chunks[chunks.length - 1];
}
return [{ json: { ...ctx, escalationRecommendation: text || '(no recommendation generated)' } }];
